 @Test void approvedBonusReallyPaysGrossCpfSdlAndKeepsPrivateEvidenceOutOfPayslip(){fixed(false);var event=bonus(UUID.randomUUID(),"10000");approveBonus(event);var batches=batches();var b=calculated(batches);var line=b.calculation().lines().getFirst();assertThat(line.issues()).isEmpty();assertThat(line.grossPay()).isEqualTo("18000.00");assertThat(line.employeeCpf()).isEqualTo("3600.00");assertThat(line.sdl()).isEqualTo("11.25");assertThat(line.aw().cpfAW()).isEqualTo("10000.00");assertThat(line.aw().annualOW()).isEqualTo("24000.00");var confirmed=batches.action(admin,sibling,b.batch().id(),UUID.randomUUID(),new ActionWrite(b.batch().version(),"confirm","confirmed"));assertThat(jdbc.queryForObject("select count(*) from workforce_wage_event_consumptions where tenant_id=? and active",Integer.class,tenant)).isEqualTo(1);var frozen=jdbc.queryForObject("select calculation::text from workforce_pay_batches where id=?",String.class,b.batch().id());var slip=new PayslipService(access,new PayrollAccess(access,directory,jdbc),new PayrollRepository(jdbc,json),repository).preview(admin,store,b.batch().id(),employee);assertThat(json.write(slip)).doesNotContain("PRIVATE-","eventEvidence","governance","sourceFingerprint","annualOW");assertThat(slip.line().publicAw().rawAW()).isEqualTo("10000.00");var evidence=annual.assessments(tenant,company,employee,2026);assertThat(evidence).hasSize(1);assertThat(evidence.getFirst().context().months()).hasSize(12);assertThat(evidence.getFirst().context().months().get(10).state()).isEqualTo("forecast");assertThat(evidence.getFirst().assessment().allocations()).hasSize(1);assertThat(jdbc.queryForObject("select calculation::text from workforce_pay_batches where id=?",String.class,b.batch().id())).isEqualTo(frozen);assertThat(batches.detail(admin,store,b.batch().id()).sourceChanged()).isFalse();assertThatThrownBy(()->laterYears().save(admin,store,company,employee,2026,new AnnualWageDtos.Write(UUID.randomUUID(),0L,List.of(opening("2026-10","8000")),"cannot replace frozen actual"))).hasMessage("ANNUAL_INTERNAL_FACT_PROTECTED");}
 @Test void unknownAnnualHistoryBlocksCpfAndNetButNotKnownSdlAndForeignNeedsNoQuota(){fixed(false);jdbc.update("update workforce_employees set hire_date='2026-01-01' where tenant_id=? and id=?",tenant,employee);approveBonus(bonus(UUID.randomUUID(),"1000"));var b=calculated(batches());var line=b.calculation().lines().getFirst();assertThat(line.employeeCpf()).isNull();assertThat(line.netPay()).isNull();assertThat(line.sdl()).isEqualTo("11.25");assertThat(b.calculation().totalNet()).isNull();assertThat(PayBreakdown.of(b.calculation()).employerCost()).isNull();assertThat(line.issues()).contains("ANNUAL_WAGES_INCOMPLETE");}
