 @Test void confirmationWaitsForOpeningCommitAndRechecksAllOrdinaryRows()throws Exception{fixed(false);var service=batches();var batch=calculated(service);var snapshot=jdbc.queryForObject("select calculation::text from workforce_pay_batches where id=?",String.class,batch.batch().id());var written=new CountDownLatch(1);var release=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var writer=pool.submit(()->new TransactionTemplate(tx).execute(status->{var page=openingWithPriorAward();written.countDown();try{if(!release.await(15,TimeUnit.SECONDS))throw new IllegalStateException("release timeout");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}return page;}));assertThat(written.await(15,TimeUnit.SECONDS)).isTrue();var confirm=pool.submit(()->{try{service.action(admin,store,batch.batch().id(),UUID.randomUUID(),new ActionWrite(batch.batch().version(),"confirm","concurrent opening"));return "confirmed";}catch(com.rpb.reservation.workforce.domain.WorkforceException e){return e.code();}});var key="workforce.payroll.source:"+tenant;boolean waiting=false;long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(10);while(System.nanoTime()<deadline){var count=jdbc.queryForObject("select count(*) from pg_locks where locktype='advisory' and not granted and mode='ExclusiveLock' and classid::bigint=((hashtextextended(?,0)>>32)&4294967295) and objid::bigint=(hashtextextended(?,0)&4294967295)",Integer.class,key,key);if(count!=null&&count>0){waiting=true;break;}Thread.sleep(20);}assertThat(waiting).isTrue();release.countDown();var before=writer.get(20,TimeUnit.SECONDS);assertThat(confirm.get(20,TimeUnit.SECONDS)).isEqualTo("ANNUAL_OPENING_PAYROLL_CONFLICT");assertThat(jdbc.queryForObject("select calculation::text from workforce_pay_batches where id=?",String.class,batch.batch().id())).isEqualTo(snapshot);assertThat(service.detail(admin,store,batch.batch().id()).batch().status()).isEqualTo("calculated");assertThat(laterYears().read(admin,store,company,employee,2026).assessment().remainingAW()).isEqualTo(before.assessment().remainingAW()).isEqualTo("72000.00");assertThat(jdbc.queryForObject("select count(*) from workforce_wage_event_consumptions where tenant_id=?",Integer.class,tenant)).isZero();}finally{release.countDown();pool.shutdownNow();}}
 AnnualWageDtos.Page openingWithPriorAward(){var old=opening("2026-10","8000");var award=bonus(UUID.randomUUID(),"6000");return laterYears().save(admin,store,company,employee,2026,new AnnualWageDtos.Write(UUID.randomUUID(),0L,List.of(new AnnualWageDtos.OpeningMonth(old.month(),old.state(),old.rawOW(),old.cpf(),old.policyId(),old.policyVersion(),"2800","2380",old.evidenceReference(),List.of(new AnnualWageDtos.WageEvent(award.eventEvidence(),award.amount(),"external payroll")))),"original month responsibility"));}
 void preservedOpening(AnnualWageDtos.Page before,String revision,String events){var after=laterYears().read(admin,store,company,employee,2026);assertThat(after.context().months().get(9)).isEqualTo(before.context().months().get(9));assertThat(after.assessment().usedAW()).isEqualTo("6000.00");assertThat(after.assessment().remainingAW()).isEqualTo(before.assessment().remainingAW()).isEqualTo("72000.00");var nextEvidence=new WageEvents.Evidence(UUID.randomUUID(),"bonus","AW",LocalDate.of(2026,1,1),LocalDate.of(2026,11,30),null,LocalDate.of(2026,11,30),"2026-11","2026-11","future award","annual award");var next=AnnualWageRepository.current(after.context(),YearMonth.of(2026,11),new java.math.BigDecimal("8000"),opening("2026-11","8000").cpf(),policy,List.of(new AnnualWageDtos.WageEvent(nextEvidence,"80000","hypothetical next month")));assertThat(new AnnualWageCalculator().assess(next).allocations().stream().filter(a->a.eventId().equals(nextEvidence.eventId())).findFirst().orElseThrow().eligibleAW()).isEqualTo("72000.00");assertThat(jdbc.queryForObject("select snapshot::text from workforce_statutory_year_revisions where tenant_id=?",String.class,tenant)).isEqualTo(revision);assertThat(jdbc.queryForObject("select snapshot::text from workforce_wage_events where tenant_id=?",String.class,tenant)).isEqualTo(events);assertThat(jdbc.queryForObject("select count(*) from workforce_wage_event_consumptions where tenant_id=?",Integer.class,tenant)).isZero();}
 @Test void openingAwardBlocksOrdinaryOwOnlyWithoutHidingHistoricalQuota(){fixed(false);var before=openingWithPriorAward();var revision=jdbc.queryForObject("select snapshot::text from workforce_statutory_year_revisions where tenant_id=?",String.class,tenant);var events=jdbc.queryForObject("select snapshot::text from workforce_wage_events where tenant_id=?",String.class,tenant);var service=batches();var batch=calculated(service);assertThat(batch.calculation().lines().getFirst().issues()).contains("ANNUAL_OPENING_PAYROLL_CONFLICT");assertThat(batch.calculation().lines().getFirst().netPay()).isNull();assertThatThrownBy(()->service.action(admin,store,batch.batch().id(),UUID.randomUUID(),new ActionWrite(batch.batch().version(),"confirm","duplicate month"))).hasMessage("ANNUAL_OPENING_PAYROLL_CONFLICT");preservedOpening(before,revision,events);}
 @Test void openingAwardBlocksDifferentOrdinaryAwardAndItsAssumedPreview(){fixed(false);var before=openingWithPriorAward();var revision=jdbc.queryForObject("select snapshot::text from workforce_statutory_year_revisions where tenant_id=?",String.class,tenant);var events=jdbc.queryForObject("select snapshot::text from workforce_wage_events where tenant_id=?",String.class,tenant);var input=new InputWrite(0L,null,null,true,false,List.of(bonus(UUID.randomUUID(),"1000")),"different award");var r=changes.save(admin,store,UUID.randomUUID(),new Write(0L,company,employee,null,null,null,List.of(new MonthWrite("2026-10",input)),null,"different award"));var pubs=new TemplatePublicationRepository(jdbc,json,clock);var impacts=proxy(new PayChangeImpactService(changes,requestRepository,new PayChangeDrafts(requestRepository,configs,pubs,repository,clock),sourceCapture(),new PayrollCalculationService(clock),new PayrollAccess(access,directory,jdbc),new PayrollRepository(jdbc,json),clock));var preview=impacts.preview(admin,store,r.id(),"2026-10");assertThat(preview.issues()).contains("ANNUAL_OPENING_PAYROLL_CONFLICT");assertThat(preview.beforeNet()).isNull();assertThat(preview.afterNet()).isNull();approve(submit(r));var service=batches();var batch=calculated(service);assertThat(batch.calculation().lines().getFirst().aw().issues()).contains("ANNUAL_OPENING_PAYROLL_CONFLICT");assertThatThrownBy(()->service.action(admin,store,batch.batch().id(),UUID.randomUUID(),new ActionWrite(batch.batch().version(),"confirm","different award"))).hasMessage("ANNUAL_OPENING_PAYROLL_CONFLICT");preservedOpening(before,revision,events);assertThatThrownBy(()->laterYears().save(admin,store,company,employee,2026,new AnnualWageDtos.Write(UUID.randomUUID(),1L,before.context().openingMonths(),"cannot override approved input"))).hasMessage("ANNUAL_INTERNAL_FACT_PROTECTED");}
 @Test void openingAfterCalculationInvalidatesAndBlocksConfirmationWithoutRewritingSnapshot(){fixed(false);var service=batches();var batch=calculated(service);assertThat(batch.calculation().issues()).isEmpty();var snapshot=jdbc.queryForObject("select calculation::text from workforce_pay_batches where id=?",String.class,batch.batch().id());var before=openingWithPriorAward();var revision=jdbc.queryForObject("select snapshot::text from workforce_statutory_year_revisions where tenant_id=?",String.class,tenant);var events=jdbc.queryForObject("select snapshot::text from workforce_wage_events where tenant_id=?",String.class,tenant);assertThat(service.detail(admin,store,batch.batch().id()).sourceChanged()).isTrue();assertThatThrownBy(()->service.action(admin,store,batch.batch().id(),UUID.randomUUID(),new ActionWrite(batch.batch().version(),"confirm","opening arrived"))).hasMessage("ANNUAL_OPENING_PAYROLL_CONFLICT");assertThat(jdbc.queryForObject("select calculation::text from workforce_pay_batches where id=?",String.class,batch.batch().id())).isEqualTo(snapshot);assertThat(jdbc.queryForObject("select status from workforce_pay_batches where id=?",String.class,batch.batch().id())).isEqualTo("calculated");preservedOpening(before,revision,events);}
 @Test void midMonthFreeEmployeeKeepsContractAwardAndConsumedEventAtTheSameAmount(){fixed(false);jdbc.update("update workforce_employees set leave_date='2026-10-20' where tenant_id=? and id=?",tenant,employee);var event=bonus(UUID.randomUUID(),"1000");var prorated=new Item(event.label(),event.kind(),event.amount(),"payable",event.itemId(),null,event.eventEvidence());assertThatThrownBy(()->approveBonus(prorated)).hasMessage("WORKFORCE_INVALID");approveBonus(event);var service=batches();var b=calculated(service);var line=b.calculation().lines().getFirst();assertThat(line.issues()).isEmpty();assertThat(line.basicPay()).isEqualTo("8000.00");assertThat(line.grossPay()).isEqualTo("9000.00");assertThat(line.aw().rawAW()).isEqualTo("1000.00");service.action(admin,store,b.batch().id(),UUID.randomUUID(),new ActionWrite(b.batch().version(),"confirm","full contract award"));assertThat(new java.math.BigDecimal(jdbc.queryForObject("select snapshot->>'amount' from workforce_wage_events where tenant_id=? and event_id=?",String.class,tenant,event.eventEvidence().eventId()))).isEqualByComparingTo("1000");}
 @Test void annualReadsWritesAndReplaysRecheckTenantAndAppGate(){var command=new AnnualWageDtos.Write(UUID.randomUUID(),0L,List.of(opening("2026-09","1000")),"evidence");years.save(admin,store,company,employee,2026,command);var foreign=new CurrentActor(UUID.randomUUID(),adminId,"staff",admin.roles(),admin.permissions(),admin.storeIds());assertThatThrownBy(()->years.read(foreign,store,company,employee,2026)).hasMessage("WORKFORCE_FORBIDDEN");assertThatThrownBy(()->years.save(foreign,store,company,employee,2026,command)).hasMessage("WORKFORCE_FORBIDDEN");assertThatThrownBy(()->jdbc.update("insert into workforce_statutory_year_subjects(tenant_id,company_id,employee_id,year) values(?,?,?,2026)",foreign.tenantId(),company,employee)).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);for(var reason:List.of(com.rpb.reservation.appgate.domain.AppGateDenyReason.APP_DISABLED,com.rpb.reservation.appgate.domain.AppGateDenyReason.TENANT_APP_NOT_ENABLED,com.rpb.reservation.appgate.domain.AppGateDenyReason.STORE_APP_NOT_ENABLED)){org.mockito.Mockito.doReturn(com.rpb.reservation.appgate.domain.AppGateDecision.deny("workforce",tenant,store,"workforce.view",reason)).when(gate).evaluate(org.mockito.ArgumentMatchers.any());assertThatThrownBy(()->years.read(admin,store,company,employee,2026)).hasMessage(reason.name());assertThatThrownBy(()->years.save(admin,store,company,employee,2026,command)).hasMessage(reason.name());assertThatThrownBy(()->years.reconcile(admin,store,company,employee,2026,new AnnualWageDtos.ReconcileWrite(UUID.randomUUID(),"old","2026-12"))).hasMessage(reason.name());}assertThat(annual.saved(tenant,company,employee,2026).version()).isEqualTo(1);}
 @Test void headquartersOpeningIsVersionedIdempotentAndStorePayrollCannotForgeHistory(){var c=new AnnualWageDtos.Write(UUID.randomUUID(),0L,List.of(opening("2026-09","1000")),"opening evidence");var first=years.save(admin,store,company,employee,2026,c);assertThat(years.save(admin,store,company,employee,2026,c)).isEqualTo(first);assertThat(first.context().openingMonths()).hasSize(1);assertThat(years.read(admin,sibling,company,employee,2026).context().fingerprint()).isEqualTo(first.context().fingerprint());var id=account("store_manager",Set.of(store,sibling),Set.of("workforce.view"));admins.save(admin,store,id,new WorkforceDtos.AdministratorWrite(0L,false,company));var manager=new CurrentActor(tenant,id,"staff",Set.of("store_manager"),Set.of("workforce.view"),Set.of(store,sibling));assertThat(years.read(manager,store,company,employee,2026).context().writable()).isFalse();assertThatThrownBy(()->years.save(manager,store,company,employee,2026,new AnnualWageDtos.Write(UUID.randomUUID(),1L,List.of(opening("2026-09","0")),"fake zero"))).hasMessage("WORKFORCE_FORBIDDEN");assertThatThrownBy(()->years.save(admin,store,company,employee,2026,new AnnualWageDtos.Write(c.commandId(),0L,List.of(opening("2026-09","2000")),"changed"))).hasMessage("WORKFORCE_CONFLICT");assertThatThrownBy(()->years.save(admin,store,company,employee,2026,new AnnualWageDtos.Write(UUID.randomUUID(),1L,List.of(opening("2026-12","0")),"future"))).hasMessage("ANNUAL_INTERNAL_FACT_PROTECTED");}
 @Test void forecastRevisionStalesCalculatedBonusAndOldSnapshotsStayIntact(){fixed(false);approveBonus(bonus(UUID.randomUUID(),"1000"));var batches=batches();var before=calculated(batches);var p=configs.profiles(tenant,company).getFirst();var next=new Rule("monthly","9000","8","44",false,"1.5",List.of(),new Generation("fixed",List.of()));approve(submit(changes.save(admin,store,UUID.randomUUID(),new Write(0L,company,employee,LocalDate.of(2026,11,1),null,new ProfileWrite(0L,company,employee,LocalDate.of(2026,11,1),p.templateId(),next,p.cpf(),null,p.cdac()),List.of(),null,"future approved amount"))));assertThat(batches.detail(admin,store,before.batch().id()).sourceChanged()).isTrue();assertThatThrownBy(()->batches.action(admin,store,before.batch().id(),UUID.randomUUID(),new ActionWrite(before.batch().version(),"confirm","stale"))).hasMessage("WORKFORCE_PAYROLL_SOURCE_CHANGED");}
