 @Test void combinedProfileAndBonusHypothesisUpdatesFutureForecastWithoutWritingEffectiveFacts(){fixed(false);var p=configs.profiles(tenant,company).getFirst();var next=new Rule("monthly","4000","8","44",false,"1.5",List.of(),new Generation("fixed",List.of()));var item=bonus(UUID.randomUUID(),"90000");var r=changes.save(admin,store,UUID.randomUUID(),new Write(0L,company,employee,p.effectiveFrom(),null,new ProfileWrite(p.version(),company,employee,p.effectiveFrom(),p.templateId(),next,p.cpf(),null,p.cdac()),List.of(new MonthWrite("2026-10",new InputWrite(0L,null,null,true,false,List.of(item),"combined"))),null,"combined hypothetical"));var assumption=new PayrollSources.Assumptions(r.id(),r.revision(),r.hash(),List.of(r.content().profile()),Map.of(employee,r.content().months().getFirst().after()));var hypothetical=annual.captureForPayrollAssuming(tenant,company,employee,YearMonth.of(2026,10),assumption);assertThat(hypothetical.months().get(10).rawOW()).isEqualTo("4000.00");var current=AnnualWageRepository.current(hypothetical,YearMonth.of(2026,10),new java.math.BigDecimal("4000"),p.cpf(),policy,AnnualWageRepository.events(r.content().months().getFirst().after(),"hypothesis"));var target=new AnnualWageCalculator().assess(current);assertThat(target.awCeiling()).isEqualTo("90000.00");assertThat(target.months().get(9).targetEmployeeCpf()).isEqualTo("18800.00");var pubs=new TemplatePublicationRepository(jdbc,json,clock);var impacts=proxy(new PayChangeImpactService(changes,requestRepository,new PayChangeDrafts(requestRepository,configs,pubs,repository,clock),sourceCapture(),new PayrollCalculationService(clock),new PayrollAccess(access,directory,jdbc),new PayrollRepository(jdbc,json),clock));var preview=impacts.preview(admin,store,r.id(),"2026-10");assertThat(preview.issues()).isEmpty();assertThat(preview.afterNet()).isEqualTo("75197.00");assertThat(annual.capture(tenant,company,employee,2026).months().get(10).rawOW()).isEqualTo("8000.00");assertThat(configs.findProfile(tenant,p.id()).orElseThrow()).isEqualTo(p);assertThat(jdbc.queryForObject("select count(*) from workforce_pay_batches where tenant_id=?",Integer.class,tenant)).isZero();}
 @Test void earlierCompanyHistoryDoesNotBecomeZeroOnRehireAndOtherCompaniesKeepSeparateOpening(){jdbc.update("update workforce_company_history set effective_date='2026-01-01' where tenant_id=? and employee_id=?",tenant,employee);var first=annual.capture(tenant,company,employee,2026);assertThat(first.months().getFirst().state()).isEqualTo("unknown");years.save(admin,store,company,employee,2026,new AnnualWageDtos.Write(UUID.randomUUID(),0L,List.of(opening("2026-09","1000")),"earlier employment evidence"));assertThat(annual.capture(tenant,company,employee,2026).months().get(8).rawOW()).isEqualTo("1000.00");jdbc.update("insert into workforce_company_history(employee_id,tenant_id,company_id,effective_date,version) values(?,?,?,'2026-11-01',2)",employee,tenant,otherCompany);years.save(admin,otherStore,otherCompany,employee,2026,new AnnualWageDtos.Write(UUID.randomUUID(),0L,List.of(opening("2026-09","2000")),"other employer historical evidence"));assertThat(annual.capture(tenant,otherCompany,employee,2026).months().get(8).rawOW()).isEqualTo("2000.00");assertThat(annual.capture(tenant,company,employee,2026).months().get(8).rawOW()).isEqualTo("1000.00");}
 @Test void oldPendingContentHashAndBaselineSurviveAbsentNullableEventEvidence(){var c=personal(0,"4000");var r=changes.save(admin,store,UUID.randomUUID(),c);String hash=r.hash();assertThat(json.write(r.content())).doesNotContain("eventEvidence","\"upgrade\"");var raw=jdbc.queryForObject("select content::text from workforce_pay_change_revisions where request_id=? and revision=?",String.class,r.id(),r.revision());assertThat(requestRepository.hash(json.read(raw,Content.class))).isEqualTo(hash);var submitted=submit(r);var command=action(submitted,"approve");var approved=changes.action(admin,store,r.id(),command);assertThat(approved.status()).isEqualTo("approved");assertThat(changes.action(admin,store,r.id(),command)).isEqualTo(approved);assertThat(approved.hash()).isEqualTo(hash);}
 @Test void eventCannotBeConsumedTwiceAndVoidRebuildPreservesFrozenRecord(){fixed(false);var item=bonus(UUID.randomUUID(),"1000");approveBonus(item);var service=batches();var first=calculated(service);var confirmed=service.action(admin,store,first.batch().id(),UUID.randomUUID(),new ActionWrite(first.batch().version(),"confirm","confirm"));var snapshot=jdbc.queryForObject("select snapshot::text from workforce_wage_events where tenant_id=? and event_id=?",String.class,tenant,item.eventEvidence().eventId());var command=new ActionWrite(confirmed.batch().version(),"void","void for rebuild");service.action(admin,store,first.batch().id(),UUID.randomUUID(),command);var rebuilt=calculated(service);service.action(admin,store,rebuilt.batch().id(),UUID.randomUUID(),new ActionWrite(rebuilt.batch().version(),"confirm","rebuild"));assertThat(jdbc.queryForObject("select count(*) from workforce_wage_event_consumptions where tenant_id=? and active",Integer.class,tenant)).isEqualTo(1);assertThat(jdbc.queryForObject("select count(*) from workforce_wage_event_consumptions where tenant_id=?",Integer.class,tenant)).isEqualTo(2);assertThat(jdbc.queryForObject("select snapshot::text from workforce_wage_events where tenant_id=? and event_id=?",String.class,tenant,item.eventEvidence().eventId())).isEqualTo(snapshot);}
 @Test void yearEndCrossAgeReconciliationIsImmutableIdempotentAndNeverCreatesSalaryOrPayment(){var end=Clock.fixed(Instant.parse("2027-01-05T00:00:00Z"),ZoneOffset.UTC);var repo=new AnnualWageRepository(jdbc,json,end);var service=proxy(new AnnualWageService(access,new PayrollAccess(access,directory,jdbc),directory,repo,new StatutoryPolicyRepository(jdbc,json),repository,audit,end));var cpf=new StatutoryDtos.CpfProfile("citizen",LocalDate.of(1971,6,1),null,"GG","");var facts=new ArrayList<AnnualWageDtos.OpeningMonth>();for(int i=1;i<=12;i++){var month=YearMonth.of(2026,i);var events=new ArrayList<AnnualWageDtos.WageEvent>();if(i==2||i==8){var ev=new WageEvents.Evidence(UUID.randomUUID(),"bonus","AW",LocalDate.of(2026,1,1),month.atEndOfMonth(),null,month.atEndOfMonth(),month.toString(),month.toString(),"external bonus voucher","annual performance award");events.add(new AnnualWageDtos.WageEvent(ev,i==2?"20000.49":"4000.49","external payroll"));}facts.add(new AnnualWageDtos.OpeningMonth(month.toString(),"actual",i<=6?"8000":"5000",cpf,policy.id(),1L,i==2?"2800":i<=6?"1600":"900",i==2?"2380":i<=6?"1360":"800","external full original-month liability",events));}var page=service.save(admin,store,company,employee,2026,new AnnualWageDtos.Write(UUID.randomUUID(),0L,facts,"full external ledger"));var request=new AnnualWageDtos.ReconcileWrite(UUID.randomUUID(),page.context().fingerprint(),"2026-12");var result=service.reconcile(admin,store,company,employee,2026,request);assertThat(result.assessment().totalDelta()).isEqualTo("6540.00");assertThat(result.assessment().employeeDelta()).isEqualTo("3519.00");assertThat(result.assessment().employerDelta()).isEqualTo("3021.00");assertThat(service.reconcile(admin,store,company,employee,2026,request)).isEqualTo(result);assertThatThrownBy(()->jdbc.update("update workforce_aw_reconciliations set source_fingerprint='tampered' where id=?",result.id())).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(jdbc.queryForObject("select count(*) from workforce_pay_batches where tenant_id=?",Integer.class,tenant)).isZero();assertThat(jdbc.queryForObject("select count(*) from workforce_pay_payments where tenant_id=?",Integer.class,tenant)).isZero();assertThatThrownBy(()->service.save(admin,store,company,employee,2026,new AnnualWageDtos.Write(UUID.randomUUID(),1L,List.of(),"remove old event"))).hasMessage("ANNUAL_EVENT_HISTORY_IMMUTABLE");}
